package com.projetointer.backend.api;
import com.projetointer.backend.catalog.*;import com.projetointer.backend.enrollment.*;import com.projetointer.backend.user.*;import jakarta.validation.Valid;import jakarta.validation.constraints.NotNull;import java.util.*;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/api") public class AcademyController{
 private final ClassOfferingRepository classes;private final EnrollmentRepository enrollments;private final UserRepository users;
 public AcademyController(ClassOfferingRepository c,EnrollmentRepository e,UserRepository u){classes=c;enrollments=e;users=u;}
 public record ClassView(Long id,String name,String modality,String days,String timeRange,String instructor,java.math.BigDecimal price,int capacity,boolean available,String note){} public record EnrollRequest(@NotNull Long classOfferingId){} public record EnrollmentView(Long id,String className,String days,String timeRange,String instructor,String status){} public record StudentView(String name,String email,String phone,String status){} public record TeacherClassView(Long id,String name,String days,String timeRange,List<StudentView> students){}
 @GetMapping("/catalog/classes") List<ClassView> catalog(){return classes.findAllByActiveTrueOrderByIdAsc().stream().map(this::cv).toList();}
 @PostMapping("/student/enrollments") @ResponseStatus(HttpStatus.CREATED) @PreAuthorize("hasRole('STUDENT')") @Transactional EnrollmentView enroll(@Valid @RequestBody EnrollRequest r,Authentication a){var u=user(a);var c=classes.findById(r.classOfferingId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(!c.isAvailable())throw new ResponseStatusException(HttpStatus.CONFLICT,"Turma sem vagas");var old=enrollments.findByStudentIdAndClassOfferingId(u.getId(),c.getId());if(old.isPresent()){if(old.get().getStatus()!=Enrollment.Status.CANCELLED)throw new ResponseStatusException(HttpStatus.CONFLICT,"Inscrição já realizada");old.get().restore();return ev(old.get());}if(enrollments.countByClassOfferingIdAndStatusNot(c.getId(),Enrollment.Status.CANCELLED)>=c.getCapacity())throw new ResponseStatusException(HttpStatus.CONFLICT,"Turma lotada");return ev(enrollments.save(new Enrollment(u,c)));}
 @GetMapping("/student/dashboard") @PreAuthorize("hasRole('STUDENT')") Map<String,Object> student(Authentication a){var u=user(a);return Map.of("user",Map.of("name",u.getName(),"email",u.getEmail(),"phone",u.getPhone()),"enrollments",enrollments.findAllByStudentId(u.getId()).stream().filter(e->e.getStatus()!=Enrollment.Status.CANCELLED).map(this::ev).toList(),"classes",catalog());}
 @DeleteMapping("/student/enrollments/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) @PreAuthorize("hasRole('STUDENT')") void cancel(@PathVariable Long id,Authentication a){var e=enrollments.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(!e.getStudent().getId().equals(user(a).getId()))throw new ResponseStatusException(HttpStatus.NOT_FOUND);e.cancel();enrollments.save(e);}
 @GetMapping("/teacher/dashboard") @PreAuthorize("hasRole('TEACHER')") Map<String,Object> teacher(Authentication a){var u=user(a);var list=classes.findAllByTeacherIdAndActiveTrue(u.getId()).stream().map(c->new TeacherClassView(c.getId(),c.getName(),c.getDays(),c.getTimeRange(),enrollments.findAllByClassOfferingId(c.getId()).stream().filter(e->e.getStatus()!=Enrollment.Status.CANCELLED).map(e->new StudentView(e.getStudent().getName(),e.getStudent().getEmail(),e.getStudent().getPhone(),e.getStatus().name())).toList())).toList();return Map.of("teacher",Map.of("name",u.getName(),"email",u.getEmail()),"classes",list);}
 private User user(Authentication a){return users.findByEmailIgnoreCase(a.getName()).orElseThrow();}private ClassView cv(ClassOffering c){return new ClassView(c.getId(),c.getName(),c.getModality(),c.getDays(),c.getTimeRange(),c.getInstructor(),c.getPrice(),c.getCapacity(),c.isAvailable(),c.getNote());}private EnrollmentView ev(Enrollment e){var c=e.getClassOffering();return new EnrollmentView(e.getId(),c.getName(),c.getDays(),c.getTimeRange(),c.getInstructor(),e.getStatus().name());}
}
